parameters.query:
UPDATE vehicle_notifications
SET status = 'sent',
    "emailSentAt" = NOW()
WHERE id = {{ $('Update to sent waiting').item.json.id }}
RETURNING *;

UPDATE vehicle_notifications
SET status = 'sent_waiting',
    confirmation_token = '{{ $json.confirmationToken }}',
    token_expires_at = NOW() + INTERVAL '3 days'
WHERE id = {{ $('Any Notifications?').item.json.id }}
RETURNING *;

